import { Outlet, NavLink, useLocation } from 'react-router-dom'
import {
  LayoutDashboard, MessageSquare, ListTree, Puzzle, Brain,
  Terminal, Wrench, Users, Database, Clock, Settings, Menu, X,
  PanelLeftClose, PanelLeftOpen, Bell, User,
  Activity, ClipboardList, FolderKanban, GitBranch
} from 'lucide-react'
